import{c as e}from"./chunk-M2QACEQF.js";e();var a=[{slug:"mercedes-cla45-indoor-detailing-bay-hire",title:"Mercedes CLA45 Indoor Detailing Bay Hire",description:"Mercedes CLA45 detailing bay hire case study featuring an indoor wash, machine polish and ceramic coating in an air-conditioned Norwich studio.",summary:"A professional detailer hired the Auto Opulence studio to complete a full exterior preparation and protection project on this black Mercedes CLA45. The car was washed with access to our indoor wash bay and spotless-water system, machine polished beneath dedicated detailing lights and ceramic coated without being moved outside. From summer heatwaves to heavy storms, the air-conditioned studio provides a dependable place to complete demanding work in controlled conditions.",images:[{src:"/images/case-studies/mercedes-cla45-bay-hire/mercedes-cla45-valet-bay-hire.webp",alt:"Black Mercedes CLA45 after indoor detailing bay hire at Auto Opulence in Norwich"},{src:"/images/case-studies/mercedes-cla45-bay-hire/mercedes-cla45-rear-finish.webp",alt:"Rear three-quarter view of the machine-polished and ceramic-coated Mercedes CLA45"},{src:"/images/case-studies/mercedes-cla45-bay-hire/mercedes-cla45-front-finish.webp",alt:"Front view of the glossy Mercedes CLA45 inside the Auto Opulence detailing studio"}],serviceSlugs:["trade-hire-full-day"],serviceLinks:[{title:"Trade Full-Day Bay Hire",category:"Professional Hire",href:"/service/trade-hire-full-day"},{title:"Public Full-Day Bay Hire",category:"Private Hire",href:"/service/public-hire-full-day"},{title:"Indoor Wash Bay and Spotless Water",category:"Studio Equipment",href:"/about#equipment"},{title:"Valet Bay Hire Options",category:"Half-Day and Full-Day Hire",href:"/category/valet-bay-hire"}],processSections:[{title:"Climate-controlled studio hire",text:"The CLA45 remained inside throughout the project. Air conditioning helped maintain a more comfortable working environment during hot weather, while the enclosed studio removed the risk of rain, wind and airborne outdoor contamination interrupting the detail."},{title:"Indoor wash with spotless water",text:"The visiting detailer washed the Mercedes in the dedicated indoor wash area, with floor drainage and an inline spotless-water system available. This allowed the exterior to be cleaned and rinsed in the same unit before the paintwork was inspected under the studio lighting."},{title:"Machine polishing under inspection lights",text:"Once clean and dry, the black paintwork was machine polished beneath the bay's bright wall and overhead lighting. The lighting made it easier to monitor the finish across the bonnet, sides and detailed bodywork before protection was applied."},{title:"Ceramic coating completed indoors",text:"The ceramic coating was applied without the CLA45 needing to leave the controlled workspace. Completing washing, correction and coating in one indoor location gave the detailer a consistent environment and produced the deep, reflective finish shown in the completed gallery."}],externalLinks:[{label:"Auto Opulence Detailing on Instagram",href:"https://www.instagram.com/autoopulencedetailing"}],processKicker:"The studio-hire project",processHeading:"Washed, polished and coated indoors.",processIntro:"The air-conditioned studio brings the wash bay, spotless water, inspection lighting and detailing workspace together under one roof.",review:"Shoutout to Auto Opulence for letting me hire their studio! Heatwave or storms \u2014 Auto Opulence has you covered.",reviewAuthor:"Professional detailer",reviewSource:"Instagram",ctaHeading:"Book a dependable place to detail.",ctaText:"Choose half-day or full-day indoor unit hire for professional detailing, personal projects, machine polishing and ceramic coating\u2014whatever the weather outside.",secondaryCta:{label:"View bay hire options",href:"/category/valet-bay-hire"},status:"published"},{slug:"audi-tt-valet-bay-hire",title:"Audi TT Valet Bay Hire",description:"Audi TT valet bay hire case study showing how a private owner used our indoor detailing bay and their own car-care products in Norwich.",summary:"This grey Audi TT visited the Auto Opulence detailing bay for a private preparation session before travelling to the Better Car Care open day. The owner brought their preferred Stj\xE4rnagloss cleaning products and used the purpose-built indoor space to work through the vehicle without weather interruptions. The finished paintwork, wheels and motorsport-inspired cabin were ready for the next day's event.",images:[{src:"/images/case-studies/audi-tt-valet-bay-hire/audi-tt-valet-bay-hire.webp",alt:"Grey Audi TT prepared inside the Auto Opulence valet bay in Norwich"},{src:"/images/case-studies/audi-tt-valet-bay-hire/audi-tt-rear-detail.webp",alt:"Rear three-quarter view of the Audi TT in the indoor detailing bay"},{src:"/images/case-studies/audi-tt-valet-bay-hire/audi-tt-paint-reflections.webp",alt:"Glossy grey Audi TT paintwork under the valet bay inspection lighting"},{src:"/images/case-studies/audi-tt-valet-bay-hire/audi-tt-wheel-detail.webp",alt:"Audi TT wheel and clean bodywork after private bay hire"},{src:"/images/case-studies/audi-tt-valet-bay-hire/audi-tt-interior-detail.webp",alt:"Audi TT motorsport interior with Sparco seats inside the Auto Opulence bay"}],serviceSlugs:[],serviceLinks:[{title:"Public Valet Bay Hire",category:"Private Hire",href:"/category/valet-bay-hire"},{title:"Trade Valet Bay Hire",category:"Professional Hire",href:"/category/valet-bay-hire"},{title:"Indoor Wash and Detailing Equipment",category:"Included Facilities",href:"/about#equipment"}],processSections:[{title:"A weatherproof place to work",text:"The Audi was prepared entirely inside our bright, purpose-built detailing bay. With washing, detailing and finishing space available in one place, the owner could work through the car without rain, wind or changing outdoor conditions interrupting the session."},{title:"Bring your preferred products",text:"The owner brought their own Stj\xE4rnagloss car-care products for the session. Private bay hire gives enthusiasts the flexibility to use familiar products and techniques while benefiting from a clean, well-lit professional environment."},{title:"Lighting that reveals the finish",text:"The bay's bright overhead and wall lighting made it easier to inspect the grey paintwork, wheels and detailed areas as the work progressed. The controlled indoor setting helped the owner achieve a consistent finish before the car left for the open day."},{title:"Prepared for the open day",text:"With the exterior, wheels and motorsport-inspired cabin looking sharp, the Audi TT was ready for the drive to the Better Car Care open day. The session shows how both private owners and automotive professionals can use the bay for focused vehicle preparation."}],externalLinks:[{label:"Better Car Care on Instagram",href:"https://www.instagram.com/better_carcare/"},{label:"Stj\xE4rnagloss on Instagram",href:"https://www.instagram.com/stjarnagloss/"}],processKicker:"The bay-hire session",processHeading:"Prepared indoors, whatever the weather.",processIntro:"A private bay-hire session gives owners access to a clean, controlled workspace while retaining the freedom to use their own preferred car-care products.",review:"",reviewAuthor:"",ctaHeading:"Hire the bay. Work your way.",ctaText:"Private owners and automotive professionals can book our indoor bay, bring their preferred products and complete washing, detailing or polishing in one weatherproof workspace.",secondaryCta:{label:"View bay hire options",href:"/category/valet-bay-hire"},status:"published"},{slug:"volvo-xc60-end-of-lease-valet",title:"Volvo XC60 End-of-Lease Valet",description:"Volvo XC60 end-of-lease valeting case study covering deep interior cleaning, boot-carpet care, scratch reduction and collection in Norwich.",summary:"Auto Opulence collected this three-year-old Volvo XC60 for a thorough end-of-lease clean. Although its owner had looked after it carefully, grime had accumulated in hard-to-reach areas and within the boot carpet. After several focused hours of interior and exterior cleaning, plus the reduction of two surface scratches, the vehicle was transformed and returned directly to the customer with minimal disruption.",images:[{src:"/images/case-studies/volvo-xc60-lease-return/volvo-xc60-front-finish.webp",alt:"White Volvo XC60 after an end-of-lease valet at Auto Opulence"},{src:"/images/case-studies/volvo-xc60-lease-return/volvo-xc60-rear-finish.webp",alt:"Rear three-quarter view of the valeted Volvo XC60 ready for lease return"},{src:"/images/case-studies/volvo-xc60-lease-return/volvo-xc60-front-interior-valet.webp",alt:"Clean Volvo XC60 dashboard and front cabin after professional interior valeting"},{src:"/images/case-studies/volvo-xc60-lease-return/volvo-xc60-rear-interior-valet.webp",alt:"Volvo XC60 rear seats and carpets after end-of-lease interior cleaning"}],serviceSlugs:["premium-exterior-interior-valet","factory-restored-interior-valet","stage-1-vehicle-machine-polish"],serviceLinks:[{title:"Complete Interior & Exterior Valet",category:"Vehicle Valeting",href:"/service/premium-exterior-interior-valet"},{title:"Deep Interior and Boot Clean",category:"Interior Valeting",href:"/service/factory-restored-interior-valet"},{title:"Surface Scratch Reduction",category:"Vehicle Polishing",href:"/service/stage-1-vehicle-machine-polish"},{title:"Vehicle Collection & Delivery",category:"Customer Convenience",href:"/contact"}],processSections:[{title:"Collected for convenience",text:"The XC60 was collected from the customer under our motor trade policy, allowing the end-of-lease preparation to be completed without disrupting their day. On arrival, the three-year-old vehicle was inspected so the areas most likely to affect its return presentation could be prioritised."},{title:"Detailed cabin and boot cleaning",text:"The interior was cleaned methodically, including the seats, carpets, trims, controls and difficult gaps where everyday grime can collect. Particular attention was given to the boot carpet and other hard-to-reach areas so the complete cabin presented as clean and well cared for at handover."},{title:"Surface scratch reduction",text:"Two visible surface scratches were assessed and carefully reduced as part of the preparation. Treating these imperfections before the finance-company inspection improved the vehicle's overall presentation and helped the customer avoid charges that might otherwise have been applied."},{title:"Returned ready for handover",text:"After several hours of thorough interior and exterior work, the transformed Volvo was driven back to the customer. The collection-and-delivery service kept inconvenience to a minimum, while the completed valet gave the owner greater confidence when returning the vehicle at the end of its lease."}],review:"",reviewAuthor:"",ctaHeading:"Return your lease with confidence.",ctaText:"Request an end-of-lease cleaning quote before your handover date. Collection and delivery can be arranged under our motor trade policy, with courtesy vehicles available when booking selected higher-level packages.",secondaryCta:{label:"Request a lease-return quote",href:"/contact"},status:"published"},{slug:"bmw-e21-3-series-restoration-detail",title:"BMW E21 3 Series Restoration Detail",description:"BMW E21 3 Series detailing case study featuring an interior deep clean, paint correction, engine-bay detail and Gyeon ceramic coating in Norwich.",summary:"This factory-original BMW E21 3 Series arrived with its original paint, glass, matching numbers and original dealer-supplied number plates. Although the 45-year-old car had clearly been cared for, decades of use had dulled its red paintwork and marked the light interior. Over 18 focused hours, Auto Opulence deep-cleaned the cabin, corrected the paint, detailed the engine bay and applied Gyeon ceramic protection while respecting the car's originality.",images:[{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-auto-opulence.webp",alt:"Factory-original red BMW E21 3 Series after restoration detailing at Auto Opulence"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-restoration-detail.webp",alt:"BMW E21 restoration detail showing the corrected red paint finish"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-vehicle-valeting.webp",alt:"Rear three-quarter view of the valeted BMW E21 3 Series"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-car-washing-norwich.webp",alt:"BMW E21 hand car washing and detailing result in Norwich"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-car-wash.webp",alt:"Rear view of the BMW E21 after professional cleaning"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-clay-bar-wash.webp",alt:"Side profile of the BMW E21 after clay-bar decontamination"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-decontamination-wash.webp",alt:"Front view of the BMW E21 after exterior decontamination washing"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-hand-car-wash.webp",alt:"Reflections across the corrected original red BMW E21 paintwork"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-machine-polish.webp",alt:"BMW E21 original paint after single-stage machine polishing"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-ceramic-coating-finish.webp",alt:"Finished BMW E21 paint correction and ceramic coating"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-ceramic-coating-norwich.webp",alt:"Rear three-quarter view of the ceramic-coated BMW E21 in Norwich"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-engine-bay-detail-norfolk.webp",alt:"BMW E21 engine bay during the professional detailing process"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-engine-bay-detail-norwich.webp",alt:"Detailed factory BMW E21 engine bay in Norwich"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-ceramic-coatings-engine-bay.webp",alt:"Restored presentation of the BMW E21 engine bay"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-interior-car-valet-norwich.webp",alt:"Light BMW E21 front interior after a deep car valet"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-interior-car-valet.webp",alt:"Original BMW E21 dashboard and front cabin after interior detailing"},{src:"/images/case-studies/bmw-e21-3-series/bmw-e21-7-year-ceramic-coating.webp",alt:"Original light BMW E21 rear seats after a deep interior clean"}],serviceSlugs:["factory-restored-interior-valet","exterior-full-decontamination-wash-with-clay-bar","stage-1-vehicle-machine-polish","multi-stage-machine-polish-inc-7-year-ceramic-coating"],serviceLinks:[{title:"Factory Restored Valet",category:"Vehicle Valeting",href:"/service/factory-restored-interior-valet"},{title:"Clay Bar Decontamination Wash",category:"Vehicle Washing",href:"/service/exterior-full-decontamination-wash-with-clay-bar"},{title:"Stage 1 Machine Polish",category:"Vehicle Polishing",href:"/service/stage-1-vehicle-machine-polish"},{title:"Engine Bay Detailing",category:"Specialist Valeting",href:"/category/vehicle-valeting"},{title:"Gyeon Ceramic Coating",category:"Vehicle Protection",href:"/service/multi-stage-machine-polish-inc-7-year-ceramic-coating"}],processSections:[{title:"Originality-first assessment",text:"Before correction began, we inspected the original red paint and measured its depth across the car. The findings were discussed with the owner so we could improve the finish without unnecessarily removing valuable factory paint. A single-stage correction was selected for most panels, with only isolated areas receiving a more focused approach."},{title:"Decades of interior use removed",text:"The light cabin received its first intensive clean in several decades. Seats, carpets, trims, controls and detailed areas were worked methodically to lift accumulated use while treating the original materials with appropriate care. The aim was a genuinely cleaner, brighter interior rather than an over-dressed finish."},{title:"Controlled paint correction",text:"After a thorough wash and bonded-contamination removal, the paint was machine polished to revive the clarity and richness that red finishes often lose with age. Correction levels were deliberately balanced panel by panel, leaving sufficient paint depth for future care while significantly improving gloss and reducing visible imperfections."},{title:"Engine bay and ceramic protection",text:"The engine bay was carefully detailed to complement the exterior and interior transformation. Once the corrected paint had been prepared and checked, Gyeon ceramic coating was applied to protect the restored gloss, improve water behaviour and make ongoing maintenance easier. The complete project required approximately 18 hours."}],review:"",reviewAuthor:"",ctaHeading:"Bring back your classic.",ctaText:"Talk to Auto Opulence about a sympathetic classic-car detail, or hire our professional indoor bay for yourself or your preferred detailer.",secondaryCta:{label:"Explore valet bay hire",href:"/category/valet-bay-hire"},status:"published"},{slug:"merl-grey-range-rover-sport-ceramic-coating",title:"Merl Grey Range Rover Sport",description:"Merl Grey Range Rover Sport ceramic coating case study featuring a decontamination wash, spotless-water preparation and Gyeon seven-year protection in Norwich.",summary:"After receiving a considerably higher dealer quote for a less comprehensive product, the owner chose Auto Opulence for a full ceramic coating package, including the Range Rover Sport's large alloy wheels. The Merl Grey pearl paint was thoroughly decontaminated and prepared before Gyeon Evo ceramic protection was applied, creating a deep, lustrous glimmer while making future maintenance easier.",images:[{src:"/images/case-studies/merl-grey-range-rover-sport/range-rover-auto-opulence-ceramic-coating.webp",alt:"Merl Grey Range Rover Sport inside the Auto Opulence detailing bay after ceramic coating"},{src:"/images/case-studies/merl-grey-range-rover-sport/range-rover-ceramic-coating-norwich.webp",alt:"Rear three-quarter view of the ceramic coated Merl Grey Range Rover Sport in Norwich"},{src:"/images/case-studies/merl-grey-range-rover-sport/range-rover-ceramic-coatings-norfolk.webp",alt:"Front three-quarter view showing the Range Rover Sport's pearl paint and coated wheels"},{src:"/images/case-studies/merl-grey-range-rover-sport/range-rover-coatings.webp",alt:"Finished Range Rover Sport ceramic coating and gloss detail"},{src:"/images/case-studies/merl-grey-range-rover-sport/range-rover-gyeon-evo-ceramic-coating.webp",alt:"Gyeon Evo ceramic coating finish on a Merl Grey Range Rover Sport"},{src:"/images/case-studies/merl-grey-range-rover-sport/range-rover-decontamination-wash.webp",alt:"Range Rover Sport after decontamination washing and ceramic protection"}],serviceSlugs:["exterior-full-decontamination-wash","multi-stage-machine-polish-inc-7-year-ceramic-coating"],serviceLinks:[{title:"Decontamination Wash",category:"Vehicle Washing",href:"/service/exterior-full-decontamination-wash"},{title:"Spotless Water",category:"Professional Equipment",href:"/about#equipment"},{title:"Gyeon 7-Year Ceramic Coating",category:"Vehicle Protection",href:"/service/multi-stage-machine-polish-inc-7-year-ceramic-coating"}],processSections:[{title:"K7-powered decontamination wash",text:"Preparation began with a thorough decontamination wash using our Kranzle K7 pressure washer. Its controlled professional output helped lift loose dirt, road film and product residue from the bodywork, wheel faces and more intricate exterior areas before contact cleaning. This created a cleaner foundation for chemical decontamination without relying on harsh automated washing."},{title:"Spotless-water final rinse",text:"Our inline spotless-water system was used through the rinsing stages to reduce the minerals that can leave water marks as a vehicle dries. On a light pearl finish such as Merl Grey, this supports a clean, consistent surface and helps us inspect the paint accurately before panel preparation and coating application."},{title:"Gyeon Evo ceramic protection",text:"Once the paintwork was fully decontaminated, prepared and checked, Gyeon Evo seven-year ceramic coating was applied to the main body. The large alloy wheels were included in the protection package, helping the vehicle resist everyday contamination while enhancing the depth and glimmer of the pearl paint."}],review:"",reviewAuthor:"",sourceUrl:"https://www.instagram.com/p/DbnVFP1CMHH/",status:"published"}];function o(t){return a.find(i=>i.slug===t)}export{a,o as b};
